def _preserve_input_dtypes(func):
    """Preserve dtypes for output columns whose values match the input."""

    def wrapped(method, data_to_wrap, original_input, estimator):
        output = func(method, data_to_wrap, original_input, estimator)
        if not (
            hasattr(output, "columns")
            and hasattr(original_input, "columns")
        ):
            return output

        for column in output.columns:
            if column not in original_input.columns:
                continue
            input_column = original_input[column]
            if not hasattr(input_column, "dtype"):
                continue
            try:
                candidate = output[column].astype(input_column.dtype)
                if candidate.equals(input_column):
                    output[column] = candidate
            except (TypeError, ValueError):
                continue
        return output

    return wrapped


